    void startDecoder(bool mesh){
        if(running_||(mesh?meshPending_:imagePending_))return;
        auto &callback=mesh?renderMesh:calculateImage;
        (mesh?meshPending_:imagePending_)=true;setRunning(running_);
        auto result=callback?callback():QJsonObject{{"error","Decoder unavailable."}};
        if(!result["started"].toBool()){decoderFinished(mesh,false,result["error"].toString("Could not start decoder."));return;}
        auto message=mesh?QString("3D decoding started; opening 3D View. Completion is reported when the mesh is loaded."):QString("2D calculation started; opening Image Preview.");
        if(result.contains("settingsSummary"))message+=" "+result["settingsSummary"].toString();
        decoderStatus_->setText(message);append("\n["+message+"]\n");
    }
